select t.id, t.slug, (select count(*) from topics t2 where t2.slug=t.slug) as slug_count from topics t join subject_levels sl on sl.id=t.subject_level_id join subjects s on s.id=sl.subject_id where s.name ilike '%physics%' and sl.level::text ilike '%a2%' and t.slug in ('magnetic-fields-and-electromagnetism','quantum-physics','nuclear-physics','oscillations-and-waves-ii','astronomy-and-cosmology') order by t.slug;
